import type { Camera, Node } from 'cc';
import { EventComponent } from '../events/EventComponent';
import type { GameState, IGameMain } from '../states/GameState';
import AppAudio from '../audio/AppAudio';
import { DualViewController } from '../controllers/DualViewController';
import StoreManager from '../store/StoreManager';
import { SlotMachineState, type SlotMachineModel } from '../reel/model/SlotMachineModel';
import { BuyFeatureController, type BuyFeatureView, type BuyFeatureEffects } from '../controllers/BuyFeatureController';
import { SpinSkipController } from '../controllers/SpinSkipController';
import { SpinShortcutController } from '../controllers/SpinShortcutController';
import { OrientationController, type OrientationView } from '../controllers/OrientationController';
import { ScatterFreeGameController } from '../controllers/ScatterFreeGameController';
import { WinBarController, type WinBarView } from '../controllers/WinBarController';
import { WinAnimationController, type WinAnimationView } from '../controllers/WinAnimationController';
import { GAME_EVENT_ID, GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import ReelTimingDebugStore from '../config/ReelTimingDebugStore';
import GameConfigManager from '../config/GameConfigManager';
import type { SlotGameDefinition } from '../models/SlotGameTypes';

/** onNormalSpin 需要用到的 reel view 子集合，各遊戲自己的 SlotMachineView/ReelView 結構相容即可傳入 */
export interface SpinBoardView {
    slotMachineView: { reelViews: { spinBet: number }[] } & {
        applySpeed(bd: number, lt: number, ed: number): void;
        applyEase(beginEase: string, endEase: string): void;
        getSpeed(): { beginDuration: number; loopTime: number; endDuration: number } | null;
        getEase(): { beginEase: string; endEase: string } | null;
    };
    slotMachineModel: SlotMachineModel;
}

/** SlotGameMain 共用 Controller 需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export type SGView = BuyFeatureView & OrientationView & WinBarView & SpinBoardView & WinAnimationView;

/**
 * SlotGameMain（SGEngine 層共用基底，介於 Core/GameMain 與各遊戲 GameMain_<gameId> 之間）
 *
 * 收斂 1001/1002 逐字重複、且不牽涉遊戲個別視覺資源（transition spine、jackpot
 * label 元件型別等）的部分：5 個共用 Controller 的實例化與 delegate 方法、
 * allViews/forEachView、免費遊戲狀態欄位、updateFgUi。
 *
 * dualView（雙向 Proxy 同步）已經上移到 Core/GameMain，因為它跟遊戲類型無關，
 * 任何遊戲都可能需要；viewH/viewV 抽象 getter 也在 Core/GameMain 宣告，這裡繼承
 * 沿用即可，不用重複宣告。
 *
 * viewH/viewV 仍由各遊戲子類別以 `@property(GameViewAdapter)` 宣告（不同遊戲的
 * GameViewAdapter 是不同的具體 class，無法塞進泛型 @property），這裡只用抽象
 * getter 存取。
 *
 * 子類別建構子/欄位初始化時機早於 gameInit()，而這幾個 Controller 需要用到
 * audioBundleName/fgTriggerScatters 等「各遊戲不同」的值——為了避免 JS 類別欄位初始化
 * 順序陷阱（base class 欄位初始化式在 super() 過程中就執行，若子類別把這些值
 * 宣告成一般欄位而非 get 方法，會讀到 undefined），Controller 改成不在欄位
 * 初始化式建立，而是由子類別在自己的 gameInit() 一開始呼叫 `initSharedControllers()`
 * 明確觸發。
 */
export abstract class SlotGameMain<TView extends SGView> extends EventComponent implements IGameMain {
    private static _instance: SlotGameMain<any> | null = null;

    public static get instance(): SlotGameMain<any> | null {
        return SlotGameMain._instance;
    }

    protected abstract get viewH(): TView;
    protected abstract get viewV(): TView | null;

    private readonly dualViewCtrl = new DualViewController<TView>({
        getViewH: () => this.viewH,
        getViewV: () => this.viewV,
    });

    protected get dualView(): TView {
        return this.dualViewCtrl.view;
    }

    public storeManager: StoreManager = null!;
    protected mainCamera: Camera | null = null;

    public get allViews(): TView[] {
        return this.viewV ? [this.viewH, this.viewV] : [this.viewH];
    }

    public forEachView(fn: (view: TView) => void): void {
        for (const view of this.allViews) {
            try {
                fn(view);
            } catch (error) {
                console.warn('[SlotGameMain] forEachView error:', error);
            }
        }
    }

    private readonly stateMap = new Map<string, GameState<IGameMain>>();
    private currentStateKey: string | null = null;
    private currentState: GameState<IGameMain> | null = null;

    protected registerState(stateKey: string, state: GameState<IGameMain>): void {
        state.init(this);
        this.stateMap.set(stateKey, state);
    }

    public hasState(stateKey: string): boolean {
        return this.stateMap.has(stateKey);
    }

    public getCurStateKey(): string | null {
        return this.currentStateKey;
    }

    public changeState(stateKey: string): void {
        if (this.currentStateKey === stateKey) return;
        const next = this.stateMap.get(stateKey);
        if (!next) {
            console.warn(`[SlotGameMain] 找不到狀態：${stateKey}`);
            return;
        }
        this.currentState?.exit();
        this.currentStateKey = stateKey;
        this.currentState = next;
        next.enter();
    }

    protected override onLoad(): void {
        super.onLoad?.();
        SlotGameMain._instance = this;
    }

    protected override start(): void {
        this.gameInit();
        this.enterGame();
    }

    public override onDestroy(): void {
        this.exitGame();
        super.onDestroy();
    }

    protected abstract gameInit(): void;
    protected abstract enterGame(): void;

    public slotMachineModel: SlotMachineModel = null!;
    private readonly registeredSlotMachineModels: SlotMachineModel[] = [];
    public abstract get definition(): SlotGameDefinition;

    /** public：供 Net/Task/FinishSpinTask 存取 */
    public pendingBuyFG = false;
    public freeSpinsRemaining = 0;
    public freeSpinsTotal = 0;
    public fgTotalWin = 0;

    /** 各遊戲自己的 AudioConfig.EFFECTSMAP 子集合 + bundle 名稱，供 BuyFeatureController 使用 */
    protected abstract get audioBundleName(): string;
    protected abstract get buyFeatureEffects(): BuyFeatureEffects;
    /** 各遊戲自己的 static FG_TRIGGER_SCATTERS，供 ScatterFreeGameController 使用 */
    protected abstract get fgTriggerScatters(): number;

    // allViews/forEachView 本體在共用的 Core/GameMain 基底

    // 快停：落下階段註冊的處理 沒有時為 null
    private quickStopHandler: (() => void) | null = null;
    // 還在等後端回應 沒進落下階段就點了快停 進落下階段時立刻套用
    private quickStopPending = false;
    // 接快停點擊的全螢幕空白節點 只在轉動中啟用 由子類別建立
    protected quickStopTouch: Node | null = null;
    // 點擊節點整轉都開著
    private quickStopWindowOpen = false;
    // 跳過到贏獎彈窗
    public readonly spinSkip = new SpinSkipController();

    public buyFeature!: BuyFeatureController;
    protected spinShortcut!: SpinShortcutController;
    protected orientation!: OrientationController;
    private scatterFG!: ScatterFreeGameController;
    private winBarCtrl!: WinBarController;
    /** protected：子類別（STOP 快捷鍵處理等場景）直接存取 this.win.xxx，沿用搬移前的呼叫慣例 */
    protected win!: WinAnimationController<TView>;

    /** 子類別必須在 gameInit() 一開始呼叫，初始化共用 Controller（見類別註解說明時機陷阱） */
    protected initSharedControllers(): void {
        this.buyFeature = new BuyFeatureController({
            getViews: () => this.allViews,
            storeManager: StoreManager.getInstance(),
            getSlotState: () => this.slotMachineModel.state,
            stopWinAnimations: () => this.stopWinAnimations(),
            audioBundleName: this.audioBundleName,
            effects: this.buyFeatureEffects,
        });

        this.spinShortcut = new SpinShortcutController({
            storeManager: StoreManager.getInstance(),
            getCurStateKey: () => this.getCurStateKey(),
            getSlotState: () => this.slotMachineModel.state,
            stopWinAnimations: () => this.stopWinAnimations(),
        });

        this.orientation = new OrientationController({
            getViewH: () => this.viewH,
            getViewV: () => this.viewV,
            getMainCamera: () => this.mainCamera,
        });

        this.scatterFG = new ScatterFreeGameController({
            isScatter: (id) => this.definition.symbols.resolve(id).kind === 'scatter',
            fgTriggerScatters: this.fgTriggerScatters,
            isPendingBuyFG: () => this.pendingBuyFG,
        });

        this.winBarCtrl = new WinBarController({
            getViews: () => this.allViews,
            storeManager: StoreManager.getInstance(),
            scheduleOnce: (cb, delay) => this.scheduleOnce(cb, delay),
        });

        this.win = new WinAnimationController<TView>({
            getViews: () => this.allViews,
            getViewH: () => this.viewH,
            storeManager: StoreManager.getInstance(),
            scheduleOnce: (cb, delay) => this.scheduleOnce(cb, delay),
        });
    }

    /** 註冊時保存實際 model，退出時不必從可能已銷毀的 View 回取。 */
    protected registerSlotMachineModel(model: SlotMachineModel): void {
        this.storeManager.registerModel(model);
        this.registeredSlotMachineModels.push(model);
    }

    protected exitGame(): void {
        for (const model of this.registeredSlotMachineModels.splice(0)) this.storeManager.unregisterModel(model);
        AppAudio.stopCurrent();
        this.currentState?.exit();
        this.currentState = null;
        this.currentStateKey = null;
        this.stateMap.clear();
        SlotGameMain._instance = null;
    }

    /** buyFeature/spinShortcut 共用的中止演出動作，delegate 給共用的 WinAnimationController */
    protected stopWinAnimations(): void {
        this.win.stopAnimations();
    }

    /** winBarCtrl/win 內的跑分/餘額捲動改用 dt 累加 這裡驅動吃到 director hook 的加速縮放 */
    protected override update(dt: number): void {
        this.winBarCtrl.update(dt);
        this.win.update(dt);
    }

    // dualView getter 本體在共用的 Core/GameMain 基底（1001/1002 各自的相容 getter 仍留在子類別，
    // 因為屬性名稱依賴各自 GameViewAdapter 型別）

    /** public：供 Net/SpinResultHandler 呼叫；ISlotGameMain 介面要求這個方法在具體類別上，實際邏輯 delegate 給共用的 WinBarController */
    public setWinBarNum(val: number): void {
        this.winBarCtrl.setWinBarNum(val);
    }

    public resetWinBar(): void {
        this.winBarCtrl.resetWinBar();
    }

    public setWinBarMul(val: number): void {
        this.winBarCtrl.setWinBarMul(val);
    }

    public showWinBarMul(val: number, isFg: boolean): void {
        this.winBarCtrl.showWinBarMul(val, isFg);
    }

    /**
     * 登記落下階段的快停處理，階段結束傳 null。
     *
     * 登記當下如果玩家已經在等後端回應時點過快停，會立刻觸發。
     *
     * @param handler 快停時要做的事；null 表示落下階段結束。
     */
    public setQuickStopHandler(handler: (() => void) | null): void {
        this.quickStopHandler = handler;
        this.setQuickStopTouchActive(handler !== null || this.quickStopWindowOpen);
        if (!handler) {
            this.quickStopPending = false;
            return;
        }
        if (this.quickStopPending) {
            this.quickStopPending = false;
            handler();
        }
    }

    /**
     * 玩家要求快停：點畫面空白處，或轉動中點 SPIN 鈕。
     *
     * 落下階段中直接快停；還在等後端回應就先記起來；其他時機（閒置、已經在播贏分演出）不處理。
     */
    public requestQuickStop(): void {
        if (this.quickStopHandler) this.quickStopHandler();
        else if (this.slotMachineModel.state === SlotMachineState.SPINNING) this.quickStopPending = true;
        this.spinSkip.request();
    }

    /**
     * 一轉開始：清掉殘留的快停要求，打開接點擊的空白節點。
     */
    public openSpinWindow(): void {
        this.quickStopPending = false;
        this.quickStopWindowOpen = this.spinSkip.keepsTouch;
        this.setQuickStopTouchActive(true);
        this.spinSkip.arm();
    }

    /**
     * 一轉結束或失敗：關掉接點擊的空白節點，清掉待處理的快停。
     */
    public closeSpinWindow(): void {
        this.quickStopPending = false;
        this.quickStopWindowOpen = false;
        this.setQuickStopTouchActive(false);
        this.spinSkip.release();
    }

    private setQuickStopTouchActive(active: boolean): void {
        if (this.quickStopTouch?.isValid) this.quickStopTouch.active = active;
    }

    public playWinBarAdd(finalNum: number): void {
        this.winBarCtrl.playWinBarAdd(finalNum);
    }

    public addWinBarScore(delta: number): void {
        this.winBarCtrl.addWinBarScore(delta);
    }

    public setTotalMultiplierLabel(acc: number): void {
        this.winBarCtrl.setTotalMultiplierLabel(acc);
    }

    public rollWinBalance(to: number, duration: number): Promise<void> {
        return this.winBarCtrl.rollWinBalance(to, duration);
    }

    public get winBarValue(): number {
        return this.winBarCtrl.winBarValue;
    }
    public set winBarValue(v: number) {
        this.winBarCtrl.winBarValue = v;
    }
    public get winBarProxy(): { v: number } {
        return this.winBarCtrl.winBarProxy;
    }
    public get winBarMulValue(): number {
        return this.winBarCtrl.winBarMulValue;
    }
    public set winBarMulValue(v: number) {
        this.winBarCtrl.winBarMulValue = v;
    }
    public get winBarMulEntered(): boolean {
        return this.winBarCtrl.winBarMulEntered;
    }
    public set winBarMulEntered(v: boolean) {
        this.winBarCtrl.winBarMulEntered = v;
    }

    /** public：供 Net/SpinResultHandler 呼叫；ISlotGameMain 介面要求這個方法在具體類別上，實際邏輯 delegate 給共用的 ScatterFreeGameController */
    public shouldEnterFreeGame(freeSpinTriggered: boolean, currentCols: number[][]): boolean {
        return this.scatterFG.shouldEnterFreeGame(freeSpinTriggered, currentCols);
    }

    /**
     * 更新免費遊戲的局數顯示 public：供 Net/SpinResultHandler 呼叫
     *
     * @param awardedRounds 這次變動裡再觸發加局加上來的局數 一般倒數不用帶 只轉發給 View 決定要不要播加局演出
     */
    public updateFgUi(awardedRounds: number = 0): void {
        console.log(`[FG] 免費局 ${this.freeSpinsRemaining}/${this.freeSpinsTotal}，累計贏分 ${this.fgTotalWin}${awardedRounds > 0 ? `（加局 +${awardedRounds}）` : ''}`);
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.FG_ROUND_CHANGED, {
            eventId: GAME_EVENT_ID.FG_ROUND_CHANGED,
            remaining: this.freeSpinsRemaining,
            total: this.freeSpinsTotal,
            awarded: awardedRounds,
        });
    }

    /** 直版改用 Template 的購買按鈕 遊戲層的一直隱藏 */
    private isGameLayerBuyHidden(v: TView): boolean {
        return v === this.viewV;
    }

    /** public：供 Net/SpinResultHandler 呼叫 */
    public applyGameModeUi(fg: boolean): void {
        this.forEachView((v) => {
            v.buySuperBtn.node.active = !fg && !this.isGameLayerBuyHidden(v);
        });
    }

    /** public：供 Net/SpinResultHandler 呼叫 */
    public onNormalSpin(): void {
        if (this.slotMachineModel.state === SlotMachineState.IDLE) {
            this.stopWinAnimations();
            const bet = this.storeManager.getModel('TemplateStore').betBalance;
            // 每次 spin 開始前才讀取、套用 PM 透過 DebugPanel 調整的轉輪節奏覆寫值——
            // 不在 DebugPanel 拖動滑桿當下就套，避免改到正在播放中的轉輪動畫。
            // 用 GameConfigManager.GAMEID（不是 GameConfig.code）：後者只有走過 runGameScene()
            // 完整導航流程才會被設成正確的遊戲 id，直接在 Editor 開單一遊戲場景 Preview 測試時
            // 仍是預設值（'lobby' 或空字串），永遠對不到 DebugPanel 存的 key。GAMEID 預設就是
            // "1001"，兩種測試方式都吃得到覆寫值，且跟 cascadeTiming() 用的識別碼一致。
            const timingOverride = ReelTimingDebugStore.get(GameConfigManager.GAMEID);
            console.log(`[SlotGameMain] onNormalSpin 讀取轉輪節奏覆寫值（GAMEID="${GameConfigManager.GAMEID}"）:`, timingOverride);
            this.forEachView((v) => {
                for (const reel of v.slotMachineView.reelViews) {
                    reel.spinBet = bet;
                }
                if (timingOverride) {
                    v.slotMachineView.applySpeed(timingOverride.beginDuration, timingOverride.loopTime, timingOverride.endDuration);
                    v.slotMachineView.applyEase(timingOverride.beginEase, timingOverride.endEase);
                    console.log('[SlotGameMain] 套用後 getSpeed/getEase:', v.slotMachineView.getSpeed(), v.slotMachineView.getEase());
                }
                v.slotMachineModel.spin();
            });
        }
    }

    /**
     * no-op stub：ISlotGameMain 介面宣告了這個方法，但 1001/1002 從未實作過，也沒有任何
     * Net/Task/SpinResultHandler 呼叫它（全專案搜尋 showFreeBoard 只有介面宣告這一處）。
     * 這是既有缺口，不是這次 SlotGameMain 重構造成的——先補一個 stub 讓型別檢查通過，
     * 之後如果要真的實作免費遊戲結算板，子類別可以直接 override。
     */
    public showFreeBoard(): Promise<void> {
        return Promise.resolve();
    }
}
